diff --git a/lib/treap/scheduler.hpp b/lib/treap/scheduler.hpp
index 345d1ce..b17f4fe 100644
--- a/lib/treap/scheduler.hpp
+++ b/lib/treap/scheduler.hpp
@@ -1,55 +1,1033 @@
 #pragma once

+#include <algorithm>
+#include <atomic>
 #include <cstddef>
 #include <cstdint>
+#include <cstring>
+#include <thread>
+#include <vector>
+
+#include <immintrin.h>
+#include <pthread.h>
+#include <sched.h>
+#include <sys/mman.h>
+#include <time.h>

 #include "augment.hpp"
 #include "node.hpp"
 #include "search_delete.hpp"
 #include "search_insert.hpp"

+#ifndef TREAP_SPIN
+#define TREAP_SPIN 2048
+#endif
+
 namespace treap {

-// Correctness-preserving serial scaffold for the ordered persistent-update
-// contract used by DB::Contreap. Replace this implementation with an update
-// engine that preserves the same observable versions.
+// Ordered persistent update engine.
+//
+// Nodes whose priority exceeds a threshold form the "top" of the treap; by the
+// heap property that set is closed under ancestors, and every subtree hanging
+// below it (a "unit") holds exactly the keys between two consecutive top keys.
+// The submitting thread routes each update to the worker that owns its unit.
+// Workers path-copy inside their units independently, in version order per
+// unit. A linker thread then walks versions in order, copies the short top
+// path of each update, links in the worker's new unit root and publishes the
+// version. Updates that change the top set (a new key above the threshold, or
+// the removal of a top key) split or merge units; the owning worker performs
+// the unit-level split or join and the linker performs the top-level part, so
+// every version is exactly the treap the serial algorithm would produce.
 struct scheduler {
 private:
+  enum kind_t : uint32_t {
+    k_nop = 0, k_top_ins, k_top_del, k_promote, k_unit_ins, k_unit_del, k_split, k_merge
+  };
+
+  // per-version record for the linker
+  struct rec_t {
+    uint64_t key;
+    uint32_t kind;
+    uint32_t worker;
+    uint32_t u1;
+    uint32_t u2;
+  };
+
+  // worker queue entry; results are written back in place over fields the
+  // worker has already consumed
+  struct alignas(32) entry_t {
+    union { uint64_t key; node_ptr out1; };
+    uint32_t ver;
+    uint32_t kind;
+    uint32_t u1;
+    uint32_t u2;
+    union { struct { uint32_t dep1; uint32_t dep2; } d; node_ptr out2; };
+  };
+  static_assert(sizeof(entry_t) == 32);
+
+  struct alignas(128) worker_t {
+    entry_t* ring;
+    alignas(64) std::atomic_size_t pushed;   // router
+    alignas(64) std::atomic_size_t done;     // worker
+    alignas(64) size_t router_pushed;        // router-local mirror of pushed
+    size_t linker_taken;                     // linker-local consumption count
+    size_t linker_seen;                      // linker-local copy of done
+    size_t linker_ahead;                     // linker-local prefetch cursor
+    pthread_t th;
+  };
+
+  #ifndef TREAP_RING
+#define TREAP_RING 12
+#endif
+  static constexpr size_t ring_bits = TREAP_RING;
+  static constexpr size_t ring_size = size_t(1) << ring_bits;
+  static constexpr size_t ring_mask = ring_size - 1;
+  static constexpr size_t rebalance_period = 2048;
+
   const size_t num_tasks_;
+  size_t num_workers_;
+  uint64_t theta_;
+
+  // shared arrays
+  // Version roots are stored compactly: each block of 64 versions has a
+  // 32-bit base offset into the linker's region, and each version a signed
+  // 16-bit node distance from it. Roots outside the region (the initial
+  // tree, an empty tree, serial fallback) are kept aside.
+  uint32_t* const rbase_;    // per block: base offset + 1, 0 while unset
+  int16_t* const rdelta_;
+  node_ptr* const xroots_;
+  node_ptr const root0_;
+  uintptr_t lbase_;
+  static constexpr int16_t aside = INT16_MIN;
+#ifndef TREAP_LREG_MB
+#define TREAP_LREG_MB 4096
+#endif
+  static constexpr size_t linker_region = size_t(TREAP_LREG_MB) << 20;
+  rec_t* const recs_;
+  node_ptr* uroot_;       // owner-published unit roots
+  uint32_t* uver_;        // version of the last event applied to a unit
+
+  // router state (submitting thread)
+  std::vector<uint64_t> tk_;     // sorted top keys
+  std::vector<uint64_t> tval_;   // their multiplicities
+  std::vector<uint32_t> gunit_;  // unit of each gap (size tk_.size()+1)
+  uint32_t* owner_;
+  uint32_t* last_def_;
+  uint32_t* pending_dep_;
+  uint32_t* cnt_;
+  size_t num_units_;
+  size_t max_units_;
+  size_t since_rebalance_;
   size_t num_issued_;
-  node_ptr* roots_;
+  size_t linked_seen_;
+
+  // linker state
+  node_ptr* lroot_;
+
+  alignas(128) std::atomic_size_t routed_;
+  alignas(128) std::atomic_size_t done_;
+  alignas(128) std::atomic_bool stop_;
+  worker_t* workers_;
+  pthread_t linker_;
+  pthread_t prefaulter_;
+
+  // Engine threads get small stacks, and bookkeeping arrays come straight
+  // from the kernel without huge pages: sparse arrays then only cost the
+  // pages actually touched, whatever the transparent huge page policy is.
+  template <class T>
+  static T* raw_array(size_t n) {
+    const size_t bytes = ((n * sizeof(T)) + 4095) & ~size_t(4095);
+    void* p = mmap(nullptr, bytes, PROT_READ | PROT_WRITE,
+                   MAP_PRIVATE | MAP_ANONYMOUS | MAP_NORESERVE, -1, 0);
+    if (p == MAP_FAILED) { return static_cast<T*>(mi_malloc_aligned(bytes, 64)); }
+    madvise(p, bytes, MADV_NOHUGEPAGE);
+    return static_cast<T*>(p);
+  }
+
+  struct start_t {
+    scheduler* self;
+    size_t idx;
+    int role;
+  };
+  start_t starts_[64];
+
+  static void* start_(void* arg) {
+    start_t* a = static_cast<start_t*>(arg);
+    if (a->role == 0) { a->self->worker_run_(a->idx); }
+    else if (a->role == 1) { a->self->linker_run_(); }
+    else { a->self->prefault_run_(); }
+    return nullptr;
+  }
+
+  pthread_t spawn_(int role, size_t idx, size_t slot) {
+    starts_[slot] = start_t{this, idx, role};
+    pthread_attr_t attr;
+    pthread_attr_init(&attr);
+    pthread_attr_setstacksize(&attr, size_t(256) << 10);
+    pthread_t t;
+    if (pthread_create(&t, &attr, &scheduler::start_, &starts_[slot]) != 0) {
+      pthread_create(&t, nullptr, &scheduler::start_, &starts_[slot]);
+    }
+    pthread_attr_destroy(&attr);
+    return t;
+  }
+  bool async_;
+
+  // readers announce snapshot requests through per-thread counters so the
+  // submitter can bound the backlog of queued queries without contention
+  static constexpr size_t max_readers = 16;
+  struct alignas(64) reader_slot { std::atomic_size_t n; };
+  reader_slot readers_[max_readers];
+  alignas(64) std::atomic_size_t num_readers_;
+  std::atomic_bool engine_live_;
+  size_t nops_;
+  size_t reads_seen_;
+  bool read_throttle_;
+#ifndef TREAP_RB
+#define TREAP_RB 4096
+#endif
+  static constexpr size_t read_backlog = TREAP_RB;
+
+  // per-thread reader state: announcement slot and the highest version seen
+  // complete, so repeated snapshot requests avoid shared cache lines
+  struct reader_tls {
+    const scheduler* owner;   // thread-local storage starts zeroed
+    size_t slot;
+    size_t seen;
+  };
+  static inline thread_local reader_tls tls_;
+
+  inline reader_tls& reader_() {
+    reader_tls& r = tls_;
+    if (r.owner != this) {
+      r.owner = this;
+      r.slot = num_readers_.fetch_add(1, std::memory_order_relaxed);
+      r.seen = 0;
+    }
+    return r;
+  }
+
+  inline void count_read_(reader_tls& r) {
+    if (r.slot < max_readers) {
+      std::atomic_size_t& n = readers_[r.slot].n;
+      n.store(n.load(std::memory_order_relaxed) + 1, std::memory_order_relaxed);
+    }
+  }
+
+  inline size_t reads_() const {
+    const size_t k = std::min<size_t>(num_readers_.load(std::memory_order_relaxed), max_readers);
+    size_t total = 0;
+    for (size_t i = 0; i < k; ++i) { total += readers_[i].n.load(std::memory_order_relaxed); }
+    return total;
+  }
+
+  // waits until readers have taken most of the queued query versions; gives
+  // up for good if no reader makes progress (snapshots may be read only
+  // after submission completes)
+  void wait_readers_() {
+    unsigned spins = 0;
+    size_t stall = 0;
+    size_t last = reads_seen_;
+    for (;;) {
+      relax(spins);
+      const size_t r = reads_();
+      if (nops_ - r <= read_backlog / 2) { reads_seen_ = r; return; }
+      if (r != last) { last = r; stall = 0; }
+      else if (++stall > TREAP_SPIN + 64 + 500) { read_throttle_ = false; return; }
+    }
+  }
+
+  arena::shared_region* shared_;
+  alignas(64) std::atomic<char*> pf_busy_{nullptr};
+  alignas(64) std::atomic_bool final_{false};
+
+  static constexpr size_t max_boxes = 16;
+  alignas(64) arena::prefault_box boxes_[max_boxes];
+  size_t num_boxes_;
+
+  void prefault_run_() {
+    char* last[max_boxes] = {};
+    for (;;) {
+      const uint32_t bell = arena::prefault_bell.load(std::memory_order_acquire);
+      bool any = false;
+      for (size_t i = 0; i < num_boxes_; ++i) {
+        char* r = boxes_[i].page.load(std::memory_order_acquire);
+        if (r != nullptr && r != last[i]) {
+          const size_t len = boxes_[i].len.load(std::memory_order_relaxed);
+          // announce the page being populated; a requester that withdraws
+          // its announcement waits for this to clear before releasing it
+          pf_busy_.store(r, std::memory_order_seq_cst);
+          if (boxes_[i].page.load(std::memory_order_seq_cst) == r) { arena::populate(r, len); }
+          pf_busy_.store(nullptr, std::memory_order_release);
+          last[i] = r;
+          any = true;
+        }
+      }
+      if (!any) {
+        if (stop_.load(std::memory_order_acquire)) { return; }
+        if (TREAP_BELL) {
+          arena::prefault_bell.wait(bell, std::memory_order_acquire);
+        } else {
+          struct timespec ts{0, 20000};
+          nanosleep(&ts, nullptr);
+        }
+      }
+    }
+  }
+
+  // Once all requests are submitted the linker stops working ahead of
+  // itself: it withdraws its spare page, returns the unused tail of its
+  // current huge page and continues on small pages, so neither ever counts
+  // toward the peak footprint while the remaining versions are linked.
+  void linker_final_phase_(arena::cursor& c) {
+    arena::prefault_box* box = c.prefault;
+    if (box != nullptr) {
+      char* spare = box->page.exchange(nullptr, std::memory_order_seq_cst);
+      unsigned spins = 0;
+      while (spare != nullptr && pf_busy_.load(std::memory_order_seq_cst) == spare) { relax(spins); }
+      if (spare != nullptr && spare >= c.cur) {
+        madvise(spare, box->len.load(std::memory_order_relaxed), MADV_DONTNEED);
+      }
+    }
+    const uintptr_t cur = (reinterpret_cast<uintptr_t>(c.cur) + 4095) & ~uintptr_t(4095);
+    const uintptr_t end = reinterpret_cast<uintptr_t>(c.end);
+    if (c.cur != nullptr && cur < end) {
+      madvise(reinterpret_cast<void*>(cur), end - cur, MADV_NOHUGEPAGE);
+      const uintptr_t page_end = (cur | (arena::huge_bytes - 1)) + 1;
+      if ((cur & (arena::huge_bytes - 1)) != 0 && page_end <= end) {
+        madvise(reinterpret_cast<void*>(cur), page_end - cur, MADV_DONTNEED);
+      }
+    }
+    // keep working ahead, in small steps on small pages
+    c.step = size_t(256) << 10;
+    c.mark = c.cur;
+  }
+
+  static inline void relax(unsigned& spins) {
+    ++spins;
+    if (spins < TREAP_SPIN) { _mm_pause(); }
+    else if (spins < TREAP_SPIN + 64) { sched_yield(); }
+    else {
+      struct timespec ts{0, 20000};
+      nanosleep(&ts, nullptr);
+    }
+  }
+
+  static inline uint32_t load_u32(const uint32_t* p) { return __atomic_load_n(p, __ATOMIC_ACQUIRE); }
+  static inline void store_u32(uint32_t* p, uint32_t v) { __atomic_store_n(p, v, __ATOMIC_RELEASE); }
+  static inline node_ptr load_ptr(node_ptr* p) { return __atomic_load_n(p, __ATOMIC_ACQUIRE); }
+  static inline void store_ptr(node_ptr* p, node_ptr v) { __atomic_store_n(p, v, __ATOMIC_RELEASE); }
+
+  // ---------------------------------------------------------------- workers
+
+  void wait_unit(uint32_t u, uint32_t dep) {
+    if (dep == 0) { return; }
+    unsigned spins = 0;
+    while (load_u32(&uver_[u]) < dep) { relax(spins); }
+  }
+
+  void worker_run_(size_t w) {
+    worker_t& me = workers_[w];
+    arena::cursor& c = arena::local;
+    c.region = shared_;
+    if (shared_ == nullptr && 1 + w < num_boxes_) { c.prefault = &boxes_[1 + w]; }
+    size_t pos = 0;
+    unsigned spins = 0;
+    for (;;) {
+      size_t avail = me.pushed.load(std::memory_order_acquire);
+      if (pos == avail) {
+        if (stop_.load(std::memory_order_acquire) && pos == me.pushed.load(std::memory_order_acquire)) { return; }
+        relax(spins);
+        continue;
+      }
+      spins = 0;
+      for (; pos < avail; ++pos) {
+        __builtin_prefetch(&me.ring[(pos + 4) & ring_mask], 1, 3);
+        entry_t& e = me.ring[pos & ring_mask];
+        const size_t ver = e.ver;
+        const uint64_t key = e.key;
+        const uint32_t kind = e.kind, u1 = e.u1, u2 = e.u2;
+        const uint32_t dep1 = e.d.dep1, dep2 = e.d.dep2;
+        wait_unit(u1, dep1);
+        node_ptr r = uroot_[u1];
+        switch (kind) {
+          case k_unit_ins:
+            r = insert_td(c, ver, r, aes_hash::hash(key), key);
+            e.out1 = r;
+            break;
+          case k_unit_del:
+            r = delete_td(c, ver, r, key);
+            e.out1 = r;
+            break;
+          case k_split: {
+            node_ptr lo, hi;
+            split_into(c, ver, r, key, &lo, &hi);
+            e.out1 = lo; e.out2 = hi;
+            r = lo;
+            uroot_[u2] = hi;
+            store_u32(&uver_[u2], uint32_t(ver));
+            break;
+          }
+          case k_merge: {
+            wait_unit(u2, dep2);
+            node_ptr other = load_ptr(&uroot_[u2]);
+            node_ptr m;
+            join_into(c, ver, r, other, &m);
+            e.out1 = m;
+            r = m;
+            break;
+          }
+          default: break;
+        }
+        uroot_[u1] = r;
+        store_u32(&uver_[u1], uint32_t(ver));
+        me.done.store(pos + 1, std::memory_order_release);
+      }
+    }
+  }
+
+  // ----------------------------------------------------------------- linker
+
+  inline entry_t& take_(uint32_t w) {
+    worker_t& wk = workers_[w];
+    const size_t idx = wk.linker_taken++;
+    if (wk.linker_seen <= idx) {
+      wk.linker_seen = wk.done.load(std::memory_order_acquire);
+      if (wk.linker_seen <= idx) {
+        unsigned spins = 0;
+        while ((wk.linker_seen = wk.done.load(std::memory_order_acquire)) <= idx) { relax(spins); }
+      }
+    }
+    return wk.ring[idx & ring_mask];
+  }
+
+  static inline bool has_entry(uint32_t kind) { return kind >= k_unit_ins; }
+
+  // copies the top path toward key down to the slot holding unit u, adding
+  // delta to every copy; the slot receives sub
+  node_ptr link_unit_(arena::cursor& c, size_t ver, node_ptr t, uint64_t key, node_ptr slot_old,
+                      node_ptr sub, int64_t delta) {
+    node_ptr root;
+    node_ptr* hook = &root;
+    while (t != slot_old) { t = copy_toward(c, ver, t, key, t->aug + delta, hook); }
+    *hook = sub;
+    return root;
+  }
+
+  // value change of a top key
+  node_ptr link_top_(arena::cursor& c, size_t ver, node_ptr t, uint64_t key, int64_t delta) {
+    node_ptr root;
+    node_ptr* hook = &root;
+    while (t->key != key) { t = copy_toward(c, ver, t, key, t->aug + delta, hook); }
+    *hook = new_node(c, ver, t->pry, t->key, t->val + delta, t->aug + delta, t->lch, t->rch);
+    return root;
+  }
+
+  // a new top key splits unit u (old root slot_old) into lo and hi
+  node_ptr link_split_(arena::cursor& c, size_t ver, node_ptr t, uint64_t key, uint64_t pry,
+                       node_ptr slot_old, node_ptr lo, node_ptr hi) {
+    node_ptr root;
+    node_ptr* hook = &root;
+    while (t != slot_old && t->pry >= pry) {
+      if (key < t->key) {
+        node_ptr n = new_node(c, ver, t->pry, t->key, t->val, t->aug + 1, nullptr, t->rch);
+        *hook = n; hook = &n->lch; t = t->lch;
+      } else {
+        node_ptr n = new_node(c, ver, t->pry, t->key, t->val, t->aug + 1, t->lch, nullptr);
+        *hook = n; hook = &n->rch; t = t->rch;
+      }
+    }
+    const uint64_t lo_sum = lo ? lo->aug : 0;
+    const uint64_t hi_sum = hi ? hi->aug : 0;
+    const uint64_t sub = t == slot_old ? lo_sum + hi_sum : t->aug;
+    node_ptr nn = new_node(c, ver, pry, key, 1, sub + 1, nullptr, nullptr);
+    *hook = nn;
+    // split the top nodes between the insertion point and the unit slot
+    node_ptr path[160];
+    uint64_t part[160];
+    int len = 0;
+    for (node_ptr y = t; y != slot_old; y = y->key < key ? y->rch : y->lch) { path[len++] = y; }
+    uint64_t l = lo_sum, h = hi_sum;
+    for (int i = len - 1; i >= 0; --i) {
+      node_ptr y = path[i];
+      if (y->key < key) { l = y->aug - h; part[i] = l; }
+      else { h = y->aug - l; part[i] = h; }
+    }
+    node_ptr* lhook = &nn->lch;
+    node_ptr* rhook = &nn->rch;
+    for (int i = 0; i < len; ++i) {
+      node_ptr y = path[i];
+      if (y->key < key) {
+        node_ptr n = new_node(c, ver, y->pry, y->key, y->val, part[i], y->lch, nullptr);
+        *lhook = n; lhook = &n->rch;
+      } else {
+        node_ptr n = new_node(c, ver, y->pry, y->key, y->val, part[i], nullptr, y->rch);
+        *rhook = n; rhook = &n->lch;
+      }
+    }
+    *lhook = lo; *rhook = hi;
+    return root;
+  }
+
+  // removal of top key; units a (left gap) and b (right gap) merge into m
+  node_ptr link_merge_(arena::cursor& c, size_t ver, node_ptr t, uint64_t key,
+                       node_ptr a_old, node_ptr b_old, node_ptr m) {
+    node_ptr root;
+    node_ptr* hook = &root;
+    while (t->key != key) {
+      if (key < t->key) {
+        node_ptr n = new_node(c, ver, t->pry, t->key, t->val, t->aug - 1, nullptr, t->rch);
+        *hook = n; hook = &n->lch; t = t->lch;
+      } else {
+        node_ptr n = new_node(c, ver, t->pry, t->key, t->val, t->aug - 1, t->lch, nullptr);
+        *hook = n; hook = &n->rch; t = t->rch;
+      }
+    }
+    node_ptr a = t->lch, b = t->rch;
+    const uint64_t a_sum = a_old ? a_old->aug : 0;
+    const uint64_t b_sum = b_old ? b_old->aug : 0;
+    for (;;) {
+      const bool ua = a == a_old, ub = b == b_old;
+      if (ua && ub) { *hook = m; break; }
+      const uint64_t sa = ua ? a_sum : a->aug;
+      const uint64_t sb = ub ? b_sum : b->aug;
+      if (ub || (!ua && a->pry > b->pry)) {
+        node_ptr n = new_node(c, ver, a->pry, a->key, a->val, sa + sb, a->lch, nullptr);
+        *hook = n; hook = &n->rch; a = a->rch;
+      } else {
+        node_ptr n = new_node(c, ver, b->pry, b->key, b->val, sa + sb, nullptr, b->rch);
+        *hook = n; hook = &n->lch; b = b->lch;
+      }
+    }
+    return root;
+  }
+
+  // Raises the top node heading the hot key range [lo, hi] to the root by
+  // boosting its priority, as a randomized search tree does for frequently
+  // accessed keys. The tree is split along the path to it: ancestors below
+  // the range form its left chain, ancestors above it its right chain, so
+  // updates in the range no longer copy the ancestors on the opposite side.
+  // The multiset is unchanged; only top nodes are copied.
+  node_ptr promote_(arena::cursor& c, size_t ver, node_ptr t, uint64_t lo, uint64_t hi) {
+    constexpr int max_path = 128;
+    node_ptr path[max_path];
+    uint64_t part[max_path];
+    int len = 0;
+    node_ptr y = t;
+    while (y != nullptr && (y->key < lo || y->key > hi)) {
+      if (len == max_path) { return t; }
+      path[len++] = y;
+      y = y->key < lo ? y->rch : y->lch;
+      if (y == nullptr || y->pry <= theta_) { return t; }   // no top key in range
+    }
+    if (y == nullptr || len == 0) { return t; }
+    const node_ptr h = y;
+    uint64_t l = h->lch ? h->lch->aug : 0;
+    uint64_t r = h->rch ? h->rch->aug : 0;
+    for (int i = len - 1; i >= 0; --i) {
+      const node_ptr a = path[i];
+      if (a->key < h->key) { l = a->aug - h->val - r; part[i] = l; }
+      else { r = a->aug - h->val - l; part[i] = r; }
+    }
+    node_ptr nh = new_node(c, ver, UINT64_MAX, h->key, h->val, t->aug, nullptr, nullptr);
+    node_ptr* lhook = &nh->lch;
+    node_ptr* rhook = &nh->rch;
